Here's a compact server that listens on a port, accepts a single client, and responds to line-based commands until the client quits or disconnects:

```c
/* server.c — minimal TCP command server: one client, then exit */
#include <stdio.h>
#include <string.h>
#include <unistd.h>
#include <signal.h>
#include <sys/socket.h>
#include <netinet/in.h>
#include <arpa/inet.h>

#define PORT 9000

static void handle_client(int fd)
{
    char buf[1024];

    dprintf(fd, "ready\n");

    for (;;) {
        ssize_t n = recv(fd, buf, sizeof(buf) - 1, 0);
        if (n <= 0)                        /* client disconnected or error */
            break;
        buf[n] = '\0';
        buf[strcspn(buf, "\r\n")] = '\0';  /* strip newline (\n or \r\n) */

        if (strcmp(buf, "ping") == 0) {
            dprintf(fd, "pong\n");
        } else if (strcmp(buf, "hello") == 0) {
            dprintf(fd, "hello from server\n");
        } else if (strncmp(buf, "echo ", 5) == 0) {
            dprintf(fd, "%s\n", buf + 5);
        } else if (strcmp(buf, "quit") == 0) {
            dprintf(fd, "bye\n");
            break;
        } else {
            dprintf(fd, "unknown command: '%s'\n", buf);
        }
    }

    close(fd);
}

int main(void)
{
    signal(SIGPIPE, SIG_IGN);  /* send() to a dead client won't kill us */

    int srv = socket(AF_INET, SOCK_STREAM, 0);
    if (srv < 0) { perror("socket"); return 1; }

    int yes = 1;
    setsockopt(srv, SOL_SOCKET, SO_REUSEADDR, &yes, sizeof(yes));

    struct sockaddr_in addr;
    memset(&addr, 0, sizeof(addr));
    addr.sin_family      = AF_INET;
    addr.sin_addr.s_addr = htonl(INADDR_ANY);  /* all interfaces */
    addr.sin_port        = htons(PORT);

    if (bind(srv, (struct sockaddr *)&addr, sizeof(addr)) < 0) {
        perror("bind"); return 1;
    }
    if (listen(srv, 1) < 0) {
        perror("listen"); return 1;
    }

    printf("listening on port %d...\n", PORT);

    struct sockaddr_in cli;
    socklen_t len = sizeof(cli);
    int fd = accept(srv, (struct sockaddr *)&cli, &len);
    if (fd < 0) { perror("accept"); return 1; }

    printf("client connected: %s\n", inet_ntoa(cli.sin_addr));
    handle_client(fd);

    close(srv);
    return 0;
}
```

**Build and run**

```sh
gcc -Wall -Wextra -o server server.c
./server
```

**Try it** (from another terminal)

```
$ nc localhost 9000
ready
ping
pong
echo hello world
hello world
quit
bye
```

**Notes**

- POSIX only (Linux/macOS/BSD). Windows requires Winsock (`WSAStartup`, `closesocket`, different headers).
- `recv()` returns whatever bytes have arrived, not necessarily a complete line — fine for short commands in a demo, but a production server would buffer input until it sees `\n`.
- `SO_REUSEADDR` lets you restart immediately without hitting "Address already in use"; ignoring `SIGPIPE` means a send to a vanished client returns `-1` instead of terminating the process.
- To serve clients one after another instead of exiting, wrap the `accept` + `handle_client` calls in a `while (1)` loop.

