    char data[BUF_SIZE];
    void (*callback)(void);
    size_t size;
};

static int major_num;
static struct class *vuln_class = NULL;
static struct device *vuln_device = NULL;

/* Global pointer — the source of the UAF */
static struct vuln_obj *g_obj = NULL;

static int vuln_open(struct inode *inode, struct file *file)
{
    return 0;
}

static int vuln_release(struct inode *inode, struct file *file)
{
    return 0;
}

static long vuln_ioctl(struct file *file, unsigned int cmd, unsigned long arg)
{
    switch (cmd) {
    case 0x1000: /* ALLOC */
        if (g_obj) {
            pr_err("vuln: object already allocated\n");
            return -EINVAL;
        }
        g_obj = kmalloc(sizeof(struct vuln_obj), GFP_KERNEL);
        if (!g_obj)
            return -ENOMEM;
        memset(g_obj, 0, sizeof(struct vuln_obj));
        g_obj->callback = NULL;
        g_obj->size = BUF_SIZE;
        pr_info("vuln: allocated object at %px\n", g_obj);
        break;

    case 0x1001: /* FREE — vulnerable: does not NULL the pointer */
        if (!g_obj) {
            pr_err("vuln: no object allocated\n");
            return -EINVAL;
        }
        kfree(g_obj);
        /* BUG: g_obj is NOT set to NULL → dangling pointer */
        pr_info("vuln: freed object (dangling ptr remains)\n");
        break;

    case 0x1002: /* USE — reads/writes through the dangling pointer */
        if (!g_obj) {
            pr_err("vuln: no object allocated\n");
            return -EINVAL;
        }
        /* UAF: g_obj points to freed memory */
        if (copy_from_user(g_obj->data, (void __user *)arg, BUF_SIZE))
            return -EFAULT;
        pr_info("vuln: wrote to freed object at %px\n", g_obj);
        break;

    case 0x1003: /* TRIGGER — calls the function pointer */
        if (!g_obj) {
            pr_err("vuln: no object allocated\n");
            return -EINVAL;
        }
        /* UAF: calls callback through dangling pointer */
        if (g_obj->callback)
            g_obj->callback();
        pr_info("vuln: triggered callback\n");
        break;

    default:
        return -EINVAL;
    }
    return 0;
}

static const struct file_operations vuln_fops = {
    .owner          = THIS_MODULE,
    .open           = vuln_open,
    .release        = vuln_release,
    .unlocked_ioctl = vuln_ioctl,
};

static int __init vuln_init(void)
{
    major_num = register_chrdev(0, DEVICE_NAME, &vuln_fops);
    if (major_num < 0) {
        pr_err("vuln: failed to register device\n");
        return major_num;
    }

    vuln_class = class_create(THIS_MODULE, CLASS_NAME);
    if (IS_ERR(vuln_class)) {
        unregister_chrdev(major_num, DEVICE_NAME);
        return PTR_ERR(vuln_class);
    }

    vuln_device = device_create(vuln_class, NULL,
                                 MKDEV(major_num, 0), NULL, DEVICE_NAME);
    if (IS_ERR(vuln_device)) {
        class_destroy(vuln_class);
        unregister_chrdev(major_num, DEVICE_NAME);
        return PTR_ERR(vuln_device);
    }

    pr_info("vuln: module loaded, device /dev/%s\n", DEVICE_NAME);
    return 0;
}

static void __exit vuln_exit(void)
{
    device_destroy(vuln_class, MKDEV(major_num, 0));
    class_destroy(vuln_class);
    unregister_chrdev(major_num, DEVICE_NAME);
    pr_info("vuln: module unloaded\n");
}

module_init(vuln_init);
module_exit(vuln_exit);
MODULE_LICENSE("GPL");
MODULE_DESCRIPTION("Educational UAF vulnerable driver");
